    "reason": "The slash stands in for a conjunction; spelling out 'and' removes the symbol."
  },
  {
    "find": "Some existing subprocess timing tests in this crate occasionally fail when the suite runs in parallel.",
    "replace": "Some existing tests of subprocess timing in this crate occasionally fail when the suite runs in parallel.",
    "type": "noun-stack",
    "reason": "Three nouns are stacked as modifiers; 'tests of subprocess timing' unpacks the phrase."
  }
]

