[
  {
    "find": "A vector database is a storage system optimized for indexing and querying high-dimensional embeddings — the numerical representations that machine learning models produce for text, images, or other data.",
    "replace": "A vector database is a storage system optimized for indexing and querying high-dimensional embeddings. Embeddings are numerical representations that machine learning models produce for text, images, or other data.",
    "type": "hard-clause",
    "reason": "The definition is one long sentence with an appositive after an em dash; splitting it makes the two ideas easier to parse."
  },
  {
    "find": "**When you probably don't:**",
    "replace": "**When you probably don't need one:**",
    "type": "telegraphic",
    "reason": "The heading drops need one, so it reads as clipped rather than as a complete idea."
  },
  {
    "find": "embedding-based retrieval surfaces conceptually related results",
    "replace": "embedding-based retrieval returns conceptually related results",
    "type": "jargon",
    "reason": "Surfaces is a business metaphor for returning or showing results."
  },
  {
    "find": "If your dataset is under ~100k vectors, a library like FAISS or even pgvector in your existing Postgres instance will likely suffice, avoiding the operational overhead of a separate service.",
    "replace": "If your dataset has under ~100k vectors, a library like FAISS, or even pgvector in your existing Postgres instance, will likely be enough. That way, you avoid the operational overhead of a separate service.",
    "type": "hard-clause",
    "reason": "The sentence is over 25 words and the trailing avoiding phrase hides the consequence; split it into the recommendation and the consequence."
  },
  {
    "find": "It's worth noting that many teams adopt a dedicated vector database prematurely, before validating that retrieval quality — not infrastructure — is the actual bottleneck.",
    "replace": "Many teams adopt a dedicated vector database too early, before validating that retrieval quality, not infrastructure, is the actual bottleneck.",
    "type": "redundant",
    "reason": "It's worth noting that is a preamble that only announces the point; removing it makes the claim direct."
  }
]

